**3b. Add `showToast()` function** — Add to the `<script>` section (after variable declarations, around line 500):

```javascript
function showToast(message, isError) {
    var toast = document.createElement('div');
    toast.style.cssText = 'position:fixed;bottom:20px;right:20px;background:' + (isError ? '#da3633' : '#238636') + ';color:#fff;padding:10px 20px;border-radius:6px;z-index:9999';
    toast.textContent = message;
    document.body.appendChild(toast);
    setTimeout(function() { toast.remove(); }, 3000);
}
```

**3c. Replace `restartClient()` function** (lines 632-648) with modal-based version:

```javascript
var _restartClientID = null;

function restartClient(clientID) {
    _restartClientID = clientID;
    document.getElementById('restart-confirm-message').textContent = 
        'Restart TUI instance ' + clientID + '? Running agents will be killed.';
    document.getElementById('restart-confirm-modal').classList.add('active');
}

function closeRestartModal(e) {
    if (e && e.target !== e.currentTarget) return;
    document.getElementById('restart-confirm-modal').classList.remove('active');
    _restartClientID = null;
}

function confirmRestart() {
    var clientID = _restartClientID;
    closeRestartModal();
    if (!clientID) return;

    fetch('/api/clients/' + encodeURIComponent(clientID) + '/restart?key=' + encodeURIComponent(_dashKey), {
        method: 'POST',
        headers: {'Content-Type': 'application/json'}
    })
    .then(function(r) { return r.json(); })
    .then(function(data) {
        if (data.error) {
            showToast('Restart failed: ' + data.error, true);
        } else {
            showToast('Restart signal sent — TUI will restart shortly');
        }
    })
    .catch(function(err) { showToast('Error: ' + err, true); });
}
```

